    /// The member's attributes.
    #[must_use]
    #[allow(clippy::indexing_slicing, reason = "the discriminants are dense from zero")]
    pub fn attributes(self) -> &'static DashaSystemAttributes {
        &ATTRIBUTES[self as usize]
    }
